def apply(inputs, premises):
    answer = {}
    n = len(inputs["asset_descriptions"])
    for i in range(n):
        description = inputs["asset_descriptions"][i]
        value = float(inputs["asset_values"][i])
        claims = []
        if inputs["governing_regime"] == "Illinois":
            if bool(inputs["asset_is_personal_nonbusiness_property"][i]):
                if inputs["output_family"] == "EV":
                    claims = [{"citation": premises["illinois_other_property_citation"], "claim_value": min(value, float(premises["illinois_other_property_limit"]))}]
                else:
                    claims = [premises["illinois_other_property_citation"]]
        elif inputs["governing_regime"] == "Federal and Wisconsin":
            if bool(inputs["asset_is_federal_household_category"][i]):
                if inputs["output_family"] == "EV":
                    claims = claims + [{"citation": premises["federal_household_citation"], "claim_value": min(value, float(premises["federal_household_item_limit"]))}]
                else:
                    claims = claims + [premises["federal_household_citation"]]
            if bool(inputs["asset_is_personal_tangible_property"][i]):
                if inputs["output_family"] == "EV":
                    claims = claims + [{"citation": premises["federal_wildcard_citation"], "claim_value": min(value, float(premises["federal_wildcard_base_limit"]))}]
                    claims = claims + [{"citation": premises["wisconsin_consumer_goods_citation"], "claim_value": min(value, float(premises["wisconsin_consumer_goods_limit"]))}]
                else:
                    claims = claims + [premises["federal_wildcard_citation"], premises["wisconsin_consumer_goods_citation"]]
        answer[description] = claims
    return {"answer": answer}

